# Teste do fluxo completo: Ata -> encaminhamento -> calendário -> ação de comunicação (materiais) -> fila de publicação -> relatórios.
# Rodar a partir da pasta do site:  python3 tests/teste_fluxo_ata_ate_publicacao.py
import asyncio, subprocess, time, os, datetime
from playwright.async_api import async_playwright
SITE=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
srv=subprocess.Popen(["python3","-m","http.server","8773","-d",SITE],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL); time.sleep(1)
def ok(c,m):
    print(("OK  " if c else "FALHOU ")+m); assert c,m
hoje=datetime.date.today(); iso=lambda d:d.isoformat()
async def aba(pg,t,**k):
    # CONecta Retiro: as ferramentas ficam numa caixa flutuante; abre a caixa da área e clica na ferramenta
    await pg.evaluate("t=>{const b=document.querySelector(`[data-tab=${t}]`);const c=b&&b.closest('.area-col');if(c&&!c.classList.contains('aberta')&&!document.querySelector('.areas.inicio'))c.querySelector('.area-titulo').click()}",t)
    await pg.click(f'[data-tab="{t}"]',**k)
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch(); ctx=await b.new_context(accept_downloads=True); await ctx.add_init_script("try{localStorage.setItem('pr_imp2611_auto','true')}catch(e){}"); pg=await ctx.new_page()
        errs=[]; dialogs=[]; pg.on("pageerror",lambda e:errs.append(str(e)))
        async def dlg(d): dialogs.append(d.message); await d.accept()
        pg.on("dialog",lambda d:asyncio.ensure_future(dlg(d)))
        await pg.goto("http://localhost:8773/login.html"); await pg.click('[data-m="cadastro"]')
        await pg.fill('#n','Admin Teste'); await pg.fill('#e','a@t.com'); await pg.fill('#s','senha12345'); await pg.fill('#s2','senha12345'); await pg.fill('#w','21999990000'); await pg.check('#cc-lgpd-ok'); await pg.click('#f button.btn-large')
        await pg.wait_for_url("**/area-restrita.html")
        # ---------- 1) ATA com encaminhamentos
        await aba(pg,'documentos'); await pg.click('[data-s="atas"]'); await pg.click('#d-novo')
        await pg.fill('#d-t','Reunião de Escola - outubro'); await pg.fill('#d-l','https://drive.google.com/ata')
        await pg.click('#d-enc-add'); await pg.click('#d-enc-add')
        L=pg.locator('.enc-linha')
        await L.nth(0).locator('[data-e="texto"]').fill('Mutirão de limpeza da trilha')
        await L.nth(0).locator('[data-e="resp"]').fill('Marcos'); await L.nth(0).locator('[data-e="data"]').fill(iso(hoje+datetime.timedelta(days=10)))
        await L.nth(0).locator('[data-e="tipo"]').select_option('Mutirão / Manutenção'); await L.nth(0).locator('[data-e="cal"]').check()
        await L.nth(1).locator('[data-e="texto"]').fill('Pedir orçamento do telhado'); await L.nth(1).locator('[data-e="resp"]').fill('Ana')
        # erro: levar ao calendário sem data
        await L.nth(1).locator('[data-e="cal"]').check(); await pg.click('#fd button.btn-large >> nth=0')
        ok('data' in (await pg.inner_text('#d-e')).lower(),"exige data para levar ao calendário")
        await L.nth(1).locator('[data-e="cal"]').uncheck(); await pg.click('#fd button.btn-large >> nth=0'); await pg.wait_for_selector('.doc-item')
        ativ=await pg.evaluate("PR_DADOS.db.get('ativ',[])"); docs=await pg.evaluate("PR_DADOS.db.get('docs',[])")
        ok(len(ativ)==1 and ativ[0]['titulo']=='Mutirão de limpeza da trilha' and ativ[0]['categoria']=='Mutirão / Manutenção' and ativ[0].get('origem')=='ata',"encaminhamento virou atividade no calendário")
        ok('Reunião' not in ativ[0]['titulo'] and 'ata' not in (ativ[0].get('descricao') or '').lower(),"atividade não expõe a ata")
        e=docs[0]['enc']; ok(len(e)==2 and e[0]['ativ']==ativ[0]['id'] and e[1]['ativ']=='',"ata guarda os 2 encaminhamentos (1 ligado ao calendário)")
        txt=await pg.inner_text('.enc-lista'); ok('Mutirão' in txt and 'no calendário' in txt and 'Pedir orçamento' in txt,"lista da ata mostra os encaminhamentos")
        ok('2' in await pg.inner_text('.tip-box'),"contador de encaminhamentos em aberto")
        await pg.select_option('select[data-es] >> nth=1','Feito'); await pg.wait_for_selector('.enc-lista')
        ok('1' in await pg.inner_text('.tip-box'),"mudar situação atualiza o contador")
        await pg.check('#l-ab'); ok(await pg.eval_on_selector_all('.doc-item','x=>x.length')==1,"filtro só atas com encaminhamentos em aberto")
        # editar a ata: mudar a data do encaminhamento ligado atualiza a atividade, sem duplicar
        await pg.click('[data-ed]'); nd=iso(hoje+datetime.timedelta(days=12)); await pg.locator('.enc-linha').nth(0).locator('[data-e="data"]').fill(nd); await pg.click('#fd button.btn-large >> nth=0'); await pg.wait_for_selector('.doc-item')
        ativ=await pg.evaluate("PR_DADOS.db.get('ativ',[])"); ok(len(ativ)==1 and ativ[0]['data']==nd,"editar a ata atualiza a atividade (sem duplicar)")
        # ---------- 2) COMUNICAÇÃO: atividade aparece em "sem comunicação planejada" (sem abrir a ata)
        await aba(pg,'comunicacao'); await pg.click('[data-s="pub"]')
        pend=await pg.inner_text('#a-pend'); ok('Mutirão de limpeza da trilha' in pend,"Comunicação enxerga a atividade vinda da ata")
        await pg.click('[data-pl]'); ok(await pg.input_value('#a-t')=='Mutirão de limpeza da trilha',"Planejar abre a ação já preenchida")
        ok('Mutirão' in await pg.eval_on_selector('#a-ev','e=>e.options[e.selectedIndex].text'),"evento relacionado já selecionado")
        await pg.fill('#a-x','Venha cuidar da trilha com a gente!'); await pg.fill('#a-pa','https://drive.google.com/pasta-mutirao')
        await pg.select_option('#fa tr[data-ri="0"] [data-f="tipo"]',label='Carrossel')
        med=await pg.inner_text('#fa tr[data-ri="0"] [data-med]'); ok('1080' in med,f"medida de referência do formato ({med})")
        await pg.select_option('#fa tr[data-ri="0"] [data-f="status"]',label='Aprovada')
        dialogs.clear(); await pg.click('#fa button.btn-large >> nth=0'); await pg.wait_for_selector('#pub-corpo table.doc-table')
        ok(any('checklist' in d for d in dialogs),"aviso quando aprovada com materiais incompletos (não bloqueia)")
        ok('Mutirão' not in await pg.inner_text('#a-pend'),"atividade sai de 'sem comunicação planejada' depois de planejada")
        ok('0/4' in await pg.inner_text('#pub-corpo table.doc-table'),"coluna Materiais mostra 0/4")
        await pg.click('[data-ae] >> nth=0')
        for k in ['briefing','texto','arte','autorizacao']: await pg.check(f'[data-mat="{k}"]')
        await pg.click('#fa button.btn-large >> nth=0'); await pg.wait_for_selector('#pub-corpo table.doc-table')
        ok('4/4' in await pg.inner_text('#pub-corpo table.doc-table'),"checklist completo = 4/4")
        # ---------- 3) FILA
        await pg.evaluate("""()=>{const l=PR_DADOS.db.get('com_posts',[]); l.forEach(p=>{p.data='%s'}); PR_DADOS.db.set('com_posts',l);}"""%iso(hoje-datetime.timedelta(days=2)))
        await pg.click('[data-s="cal"]'); await pg.click('[data-s="pub"]')
        ok(await pg.inner_text('[data-s="pub"] .badge-status')=='1',"sub-aba Publicações mostra 1 pendente/atrasada")
        await pg.click('[data-pv="fila"]'); t=await pg.inner_text('#pub-corpo'); ok('Atrasadas' in t and 'Venha cuidar' in t and 'Materiais: 4/4' in t,"fila mostra atrasada, texto e materiais")
        await pg.click('[data-fc]'); ok('Texto copiado' in await pg.inner_text('#pub-corpo') or 'copiar' in (await pg.inner_text('#pub-corpo')).lower(),"botão copiar texto responde")
        await pg.select_option('[data-fst]',label='Agendada'); ok('agendada na ferramenta' in (await pg.inner_text('#pub-corpo')).lower(),"status Agendada aparece na fila com orientação")
        async with pg.expect_download() as dl: await pg.click('#f-ics')
        d=await dl.value; path=await d.path(); ics=open(path,encoding='utf-8').read()
        ok('BEGIN:VEVENT' in ics and 'BEGIN:VALARM' in ics and 'Publicar: Mutir' in ics.replace('\r\n ',''),"agenda .ics gerada com evento e lembrete")
        await pg.click('[data-fp]'); await pg.fill('#fp-l','x'); await pg.click('[data-fpok]'); ok('http' in await pg.inner_text('#fp-e'),"link inválido é recusado")
        await pg.fill('#fp-l','https://instagram.com/p/abc'); await pg.click('[data-fpok]'); await pg.wait_for_selector('.vazio')
        po=(await pg.evaluate("PR_DADOS.db.get('com_posts',[])"))[0]; ok(po['status']=='Publicada' and po['link'].startswith('https') and po['publicadoPor']=='Admin Teste',"marcar como publicada registra link e responsável")
        ok('Nada pendente' in await pg.inner_text('#pub-corpo'),"fila esvazia depois de publicar")
        # ---------- 4) RELATÓRIOS
        await aba(pg,'relatorios'); await pg.click('[data-ab="mod"]'); await pg.select_option('#rc-m','comunicacao')
        await pg.wait_for_selector('#rc-res table'); t=await pg.inner_text('#rc-res'); ok('Planejadas' in t and 'Publicadas' in t and 'Mutirão' in t,"relatório Planejado × publicado")
        await pg.select_option('#rc-g',label='Canal'); ok('Instagram' in await pg.inner_text('#rc-res'),"agrupa por canal")
        await pg.select_option('#rc-r','acoes'); ok('4/4' in await pg.inner_text('#rc-res') and 'Carrossel' in await pg.inner_text('#rc-res'),"relatório de ações e materiais")
        await pg.select_option('#rc-m','atas'); await pg.wait_for_selector('#rc-res table'); t=await pg.inner_text('#rc-res'); ok('Pedir orçamento' in t and 'Mutirão' in t and 'Sim' in t,"relatório de encaminhamentos das atas")
        # ---------- 5) Backup inclui tudo
        bk=await pg.evaluate("PR_DADOS.montarBackup().then(b=>Object.keys(b.dados))"); ok(all(k in bk for k in ['docs','ativ','com_acoes','com_posts']),"backup inclui atas, atividades e ações")
        print("ERROS JS:",errs); ok(not errs,"sem erros de JavaScript"); await b.close()
try: asyncio.run(main())
finally: srv.terminate()
